-- Bower appliance catalogue — Hafele range, 86 products.
--
-- Replaces the 12 placeholder demo products (invented names and prices lifted
-- from the website) with Ben's actual Hafele range.
--
-- PROVENANCE, so nobody has to guess later:
--   * Identity, RRP and product photography come from the website's own
--     capture (docs/hafele-pricing-capture-2026-06-21.json), RRP as at
--     21 June 2026.
--   * Dimensions, finish, fuel type, installation type, bowl counts, bowl
--     sizes and cooking-zone layouts were read live off hafele.com.au on
--     26 July 2026. The specs live in `h3.productPropertiesSectionHeader`
--     heading/value pairs, NOT in a table — which is why the earlier capture,
--     which searched for tables, recorded the order form instead and left
--     every product with dimensions of zero.
--   * 74 of 86 have supplier-published dimensions (spec_source =
--     'product-page'). The other 12 use conventional Australian sizes
--     (spec_source = 'derived') because Hafele publish none for them.
--   * Cut-outs are NOT on the product pages — the cooktop page says
--     "Supplied with: Installation instructions and cut-out dimensions". They
--     are derived from the overall size using offsets confirmed against the
--     real drawing for 539.40.072 (590x520 overall, 560x490 cut-out).
--   * The Milano range is EXCLUDED. Ben is running that stock down, and it is
--     also the range Hafele have stopped maintaining data for.
--
-- Every row is dimensions_confirmed = false and price_is_placeholder = true.
-- Both need Ben's sign-off before they reach a customer quote; the admin
-- screen surfaces them the same way.
--
-- Prices are RRP. Sell and installed prices are deliberately left NULL for Ben
-- to set — this migration must never invent a price he would quote.

BEGIN;

-- Fail fast rather than half-load if the column migration has not run.
DO $$
BEGIN
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.columns
     WHERE table_schema = 'public' AND table_name = 'appliance_products'
       AND column_name = 'dimensions_confirmed'
  ) THEN
    RAISE EXCEPTION 'Run 20260726120000_appliance_appearance_and_dimensions.sql first';
  END IF;
END $$;

-- The 12 seeded demo products were never real. They are the only rows with no
-- item_code, so this cannot touch a genuine product.
DELETE FROM public.appliance_products
 WHERE price_is_placeholder = true
   AND item_code IS NULL;

ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name,
  brand = EXCLUDED.brand,
  category = EXCLUDED.category,
  subcategory = EXCLUDED.subcategory,
  rrp = EXCLUDED.rrp,
  width_mm = EXCLUDED.width_mm,
  height_mm = EXCLUDED.height_mm,
  depth_mm = EXCLUDED.depth_mm,
  cutout_width_mm = EXCLUDED.cutout_width_mm,
  cutout_height_mm = EXCLUDED.cutout_height_mm,
  cutout_depth_mm = EXCLUDED.cutout_depth_mm,
  finish = EXCLUDED.finish,
  power_requirements = EXCLUDED.power_requirements,
  features = EXCLUDED.features,
  image_url = EXCLUDED.image_url,
  image_is_elevation = EXCLUDED.image_is_elevation,
  installation = EXCLUDED.installation,
  bowl_count = EXCLUDED.bowl_count,
  bowl_sizes = EXCLUDED.bowl_sizes,
  product_url = EXCLUDED.product_url,
  spec_source = EXCLUDED.spec_source,
  sort_order = EXCLUDED.sort_order,
  updated_at = now();
  -- sell_price, installed_price, price_is_placeholder and
  -- dimensions_confirmed are deliberately NOT overwritten. Re-running this
  -- after Ben has priced or confirmed a product must not undo his work.

DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM public.appliance_products WHERE item_code IS NOT NULL;
  IF n <> 86 THEN
    RAISE EXCEPTION 'Expected 86 catalogue products after seeding, found %', n;
  END IF;
END $$;

COMMIT;
